      // casual/competitive
      // Pricing
      price: numeric("price"),
      // Price per session
      // Status: active/paused/ended
      status: text("status").default("active"),
      pausedAt: timestamp("paused_at"),
      endedAt: timestamp("ended_at"),
      // Multi-sport support
      sport: text("sport").default("tennis"),
      // tennis | padel | pickleball
      // Marketplace / public drop-in
      isPublic: boolean("is_public").notNull().default(false),
      // Whether this group is publicly listed for drop-in bookings
      publicDropInPrice: numeric("public_drop_in_price"),
      // Optional drop-in price per session
      courtBookingStatus: text("court_booking_status"),
      // 'academy_court' | 'external_booked' | 'external_pending'
      courtBookingNote: text("court_booking_note"),
      courtBookingUrl: text("court_booking_url"),
