    creditLedgerV2 = pgTable("credit_ledger_v2", {
      id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
      playerId: varchar("player_id").notNull().references(() => players.id, { onDelete: "cascade" }),
      academyId: varchar("academy_id").notNull().references(() => academies.id, { onDelete: "cascade" }),
      type: text("type").notNull(),
      // group | semi_private | private | money
      delta: numeric("delta").notNull(),
      // positive = credit, negative = debit
      reason: text("reason").notNull(),
      // purchase | consume | refund | makeup | manual | expiry | money_charge | money_topup
      eventKey: varchar("event_key").notNull(),
      actorId: varchar("actor_id"),
      actorRole: text("actor_role"),
      // player | coach | admin | system
      sessionId: varchar("session_id"),
      sessionPlayerId: varchar("session_player_id"),
      lotId: varchar("lot_id"),
      invoiceId: varchar("invoice_id"),
      balanceAfter: numeric("balance_after").notNull(),
      metadata: jsonb("metadata"),
      occurredAt: timestamp("occurred_at").notNull().defaultNow()
    }, (table) => [
      uniqueIndex("credit_ledger_v2_event_key_unique").on(table.eventKey),
      index("credit_ledger_v2_player_idx").on(table.playerId, table.academyId, table.occurredAt),
      // Academy-time index for shadow-mode + replay academy-wide chronological scans.
      index("credit_ledger_v2_academy_time_idx").on(table.academyId, table.occurredAt),
      index("credit_ledger_v2_session_idx").on(table.sessionId),
      index("credit_ledger_v2_session_player_idx").on(table.sessionPlayerId),
      // Task #1505 — attendance-history credit lookup: player + session_id + reason
      index("credit_ledger_v2_player_session_reason_idx").on(table.playerId, table.sessionId, table.reason),
      // Task #1332 — belt-and-suspenders against any future code path inserting a
      // second `consume` ledger row for the same session_player. The eventKey
      // unique idx already blocks the canonical write (eventKey = consume:<spId>),
      // but this partial unique idx blocks ANY consume row sharing a session_player_id
      // even if the eventKey is constructed differently (e.g. accidentally
      // suffixed with a timestamp by a future caller).
      uniqueIndex("credit_ledger_v2_no_dup_consume").on(table.sessionPlayerId).where(sql`reason = 'consume' AND session_player_id IS NOT NULL`)
    ]);
