function evaluateEarnedAchievements(stats) {
  const earned = [];
  for (const def of ACHIEVEMENT_DEFINITIONS) {
    const statValue = stats[def.triggerStat] ?? 0;
    if (statValue >= def.triggerThreshold) {
      earned.push(def.id);
    }
  }
  return earned;
}
