async function repairNullAttendance() {
  try {
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1e3).toISOString().replace("T", " ").substring(0, 19);
    const nullAttendance = await pool.query(`
      SELECT sp.id, sp.player_id, sp.session_id, s.start_time, s.session_type, s.academy_id, p.name as player_name
      FROM session_players sp
      JOIN sessions s ON s.id = sp.session_id
      JOIN players p ON p.id = sp.player_id
      LEFT JOIN player_holidays ph ON ph.player_id = sp.player_id
        AND s.start_time::date BETWEEN ph.start_date AND ph.end_date
      WHERE s.status = 'completed'
        AND s.end_time >= $1::timestamp
        AND sp.attendance_status IS NULL
        AND ph.id IS NULL
      ORDER BY s.start_time
    `, [sevenDaysAgo]);
    if (nullAttendance.rows.length === 0) {
      console.log("[NullAttendanceRepair] No completed sessions with NULL attendance found");
      return;
    }
    console.log(`[NullAttendanceRepair] Found ${nullAttendance.rows.length} completed session_player records with NULL attendance \u2014 fixing now`);
    let fixed = 0;
    let creditsProcessed = 0;
    let debtsCreated = 0;
    for (const row of nullAttendance.rows) {
      await pool.query(
        `UPDATE session_players SET attendance_status = 'present', late_minutes = 0 WHERE id = $1`,
        [row.id]
      );
      try {
        const result = await ensureCreditProcessed2(row.id, {
          academyIdHint: row.academy_id ?? null
        });
        if (result.action === "consumed") {
          creditsProcessed++;
          console.log(`[NullAttendanceRepair] ${row.player_name} | session ${row.session_id.substring(0, 8)} (${new Date(row.start_time).toISOString().substring(0, 10)}) | credit consumed`);
        } else if (result.action === "debt_created") {
          debtsCreated++;
          console.log(`[NullAttendanceRepair] ${row.player_name} | session ${row.session_id.substring(0, 8)} (${new Date(row.start_time).toISOString().substring(0, 10)}) | debt created`);
        } else if (result.action === "already_processed") {
          console.log(`[NullAttendanceRepair] ${row.player_name} | session ${row.session_id.substring(0, 8)} | already processed`);
        }
      } catch (creditError) {
        console.error(`[NullAttendanceRepair] Failed credit processing for ${row.player_name}:`, creditError);
      }
      fixed++;
    }
    console.log(`[NullAttendanceRepair] Complete: ${fixed} attendance records fixed, ${creditsProcessed} credits consumed, ${debtsCreated} debts created`);
  } catch (error) {
    console.error("[NullAttendanceRepair] Error:", error);
  }
}
async function repairV2HolidayOvercharges() {
  try {
    const overcharged = await pool.query(`
      SELECT
        cl.id            AS ledger_id,
        cl.player_id,
        cl.session_player_id,
        cl.type          AS credit_type,
        cl.delta,
        cl.academy_id,
        sp.attendance_status,
        s.start_time
      FROM credit_ledger_v2 cl
      JOIN session_players sp ON sp.id = cl.session_player_id
      JOIN sessions s ON s.id = sp.session_id
      WHERE cl.reason = 'consume'
        AND cl.delta < 0
        AND sp.attendance_status IN ('holiday', 'vacation')
        AND NOT EXISTS (
          SELECT 1 FROM credit_ledger_v2 rev
          WHERE rev.session_player_id = cl.session_player_id
            AND rev.delta > 0
            AND rev.reason IN ('refund', 'holiday_charge_reversal',
                               'manual_adjustment', 'manual')
        )
      ORDER BY s.start_time
    `);
    if (overcharged.rows.length === 0) {
      console.log("[V2HolidayRepair] No unreversed holiday consumes found");
      return;
    }
    console.log(`[V2HolidayRepair] Found ${overcharged.rows.length} unreversed holiday consume(s) \u2014 repairing`);
    const { refundCredit: refundCredit2 } = await Promise.resolve().then(() => (init_credit_engine(), credit_engine_exports));
    let fixed = 0;
    let errors = 0;
    for (const row of overcharged.rows) {
      try {
        const cancelReason = row.attendance_status === "vacation" ? "attendance_changed_to_vacation" : "attendance_changed_to_holiday";
        const result = await refundCredit2({
          sessionPlayerId: row.session_player_id,
          policy: "force",
          actorRole: "system",
          reason: cancelReason,
          ledgerReason: "holiday_charge_reversal",
          eventKey: `refund:${cancelReason}:${row.session_player_id}`
        });
        if (result.refunded) {
          console.log(
            `[V2HolidayRepair] Reversed ${result.amount} credit(s) for player ${row.player_id} session_player ${row.session_player_id} (${row.attendance_status}) | newBalance: ${result.newBalance}`
          );
          fixed++;
        } else if (result.alreadyApplied) {
          console.log(`[V2HolidayRepair] Already reversed for ${row.session_player_id}`);
        }
      } catch (err) {
        errors++;
        console.error(`[V2HolidayRepair] Failed to reverse for ${row.session_player_id}:`, err);
      }
    }
    console.log(`[V2HolidayRepair] Complete: ${fixed} reversed, ${errors} errors`);
  } catch (err) {
    console.error("[V2HolidayRepair] Error:", err);
  }
}
