async function processUnchargedAttendance() {
  try {
    const unchargedResult = await pool.query(`
      SELECT sp.id, sp.player_id, sp.attendance_status, s.session_type, s.academy_id
      FROM session_players sp
      JOIN sessions s ON s.id = sp.session_id
      JOIN academies a ON a.id = s.academy_id
      WHERE s.status = 'completed'
        AND sp.credit_deducted_at IS NULL
        AND sp.attendance_status IN ('present', 'late', 'absent')
        AND CASE
          WHEN COALESCE(a.use_new_credit_system, false) THEN
            NOT EXISTS (
              SELECT 1 FROM credit_ledger_v2 lv
              WHERE lv.session_player_id = sp.id
                AND lv.reason = 'consume'
            )
          ELSE
            NOT EXISTS (
              SELECT 1 FROM credit_transactions ct
              WHERE ct.player_id = sp.player_id
                AND ct.session_id = sp.session_id
                AND ct.amount < 0
                AND (ct.metadata->>'cancelled')::text IS DISTINCT FROM 'true'
            )
        END
      ORDER BY s.end_time ASC
      LIMIT 100
    `);
    if (unchargedResult.rows.length === 0) return;
    console.log(`[UnchargedAttendance] Found ${unchargedResult.rows.length} session_players with uncharged attendance \u2014 processing`);
    let consumed = 0;
    let debts = 0;
    let skipped = 0;
    for (const row of unchargedResult.rows) {
      try {
        const result = await ensureCreditProcessed2(row.id, {
          academyIdHint: row.academy_id ?? null
        });
        if (result.action === "consumed") consumed++;
        else if (result.action === "debt_created") debts++;
        else skipped++;
      } catch (err) {
        console.error(`[UnchargedAttendance] Failed for session_player ${row.id}:`, err);
      }
    }
    console.log(`[UnchargedAttendance] Done: ${consumed} consumed, ${debts} debts, ${skipped} skipped`);
  } catch (err) {
    console.error("[UnchargedAttendance] Error:", err);
  }
}
