      async generateJoinCode(academyId) {
        const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
        let code;
        let attempts = 0;
        do {
          code = "";
          for (let i = 0; i < 6; i++) {
            code += chars.charAt(Math.floor(Math.random() * chars.length));
          }
          const existing = await this.getAcademyByJoinCode(code);
          if (!existing) break;
          attempts++;
        } while (attempts < 10);
        await db.update(academies).set({ joinCode: code }).where(eq7(academies.id, academyId));
        return code;
      },
