            const xpDel = await tx.delete(xpTransactions).where(inArray3(xpTransactions.playerId, playerIds)).returning();
            deleted.progress = xpDel.length;
            await tx.update(players).set({ level: 1, totalXp: 0, glowScore: 50 }).where(eq7(players.academyId, id));
            deleted.playersReset = playerIds.length;
