      async deletePackage(id, academyId, force = false) {
        const pkg2 = await this.getPackage(id, academyId);
        if (!pkg2) {
          return { success: false, error: "Package not found" };
        }
        const totalCredits = Number(pkg2.totalCredits);
        const remainingCredits = Number(pkg2.remainingCredits);
        const creditsUsed = totalCredits - remainingCredits;
        if (remainingCredits > 0 && !force) {
          return {
            success: false,
            error: `Cannot delete: ${remainingCredits} unused credit(s) still remaining in this package`,
            creditsUsed
          };
        }
        const settleRows = await db.execute(sql7`
      SELECT metadata
      FROM credit_ledger_v2
      WHERE reason = 'consume_debt_settlement'
        AND lot_id IN (
          SELECT id FROM credit_lots WHERE source_package_id = ${id}
        )
    `);
        let totalDebtSettled = 0;
        for (const row of settleRows.rows) {
          const meta = typeof row.metadata === "string" ? JSON.parse(row.metadata) : row.metadata;
          totalDebtSettled += Number(meta?.settleAmount ?? 0);
        }
        await db.update(invoices).set({ packageId: null }).where(eq7(invoices.packageId, id));
        const { manualAdjustment: manualAdjustment2 } = await Promise.resolve().then(() => (init_credit_engine(), credit_engine_exports));
        if (remainingCredits > 0) {
          await manualAdjustment2({
            playerId: pkg2.playerId,
            academyId: pkg2.academyId,
            type: pkg2.creditType ?? "group",
            delta: -remainingCredits,
            reason: `package_deleted:${id}`,
            actorId: "system",
            actorRole: "system",
            eventKey: `package_delete:${id}`,
            allowOverdraw: true
          });
        }
        if (totalDebtSettled > 0) {
          await manualAdjustment2({
            playerId: pkg2.playerId,
            academyId: pkg2.academyId,
            type: pkg2.creditType ?? "group",
            delta: -totalDebtSettled,
            reason: `package_deleted_debt_reversal:${id}`,
            actorId: "system",
            actorRole: "system",
            eventKey: `package_delete_debt:${id}`,
            allowOverdraw: true,
            ledgerReason: "package_deleted_debt_reversal"
          });
        }
        await db.execute(sql7`
      UPDATE credit_lots
      SET status = 'cancelled', qty_remaining = 0
      WHERE source_package_id = ${id}
    `);
        return { success: true, creditsUsed, debtReversed: totalDebtSettled };
      },
