      // Get credit balances for multiple players (batch query for efficiency).
      //
      // Source of truth: V2 `player_credit_balance` (Task #681 Phase 3 onward).
      // The legacy `packages.remaining_credits` and "uncovered sessions" inputs
      // are no longer consulted — V2 already collapses (active credits) -
      // (consumed credits, covered or uncovered) into a single signed `credits`
      // column per (player, academy, type). Negative = owed.
      //
      // `academyId` (Task #686): when provided, the V2 read is filtered to that
      // academy so the result matches the per-academy wallet endpoint
      // (`getBalance(playerId, academyId)`) used by the player profile.
      // Without it, balances are summed across every academy the player belongs
      // to (legacy callers that don't have an academy context still get the
      // old aggregated behaviour).
      //
      // `uncoveredGroup`/`uncoveredSemiPrivate`/`uncoveredPrivate` are kept in
      // the response shape for backwards compatibility but always return 0
      // under V2 (the deficit is already baked into the signed `credits`).
      async getPlayersCreditBalances(playerIds, academyId) {
        if (playerIds.length === 0) return {};
        const result = {};
        for (const id of playerIds) {
          result[id] = { group: 0, semi_private: 0, private: 0, totalDebt: 0, groupDebt: 0, semiPrivateDebt: 0, privateDebt: 0, hasDebt: false, uncoveredGroup: 0, uncoveredSemiPrivate: 0, uncoveredPrivate: 0, netGroup: 0, netSemiPrivate: 0, netPrivate: 0 };
        }
        const balanceWhere = academyId ? and6(
          inArray3(playerCreditBalance.playerId, playerIds),
          eq7(playerCreditBalance.academyId, academyId)
        ) : inArray3(playerCreditBalance.playerId, playerIds);
        const balanceRows = await db.select({
          playerId: playerCreditBalance.playerId,
          type: playerCreditBalance.type,
          credits: playerCreditBalance.credits
        }).from(playerCreditBalance).where(balanceWhere);
        for (const row of balanceRows) {
          if (!result[row.playerId]) continue;
          const t = _normalizeCreditType(row.type);
          const credits = Number(row.credits);
          const r = result[row.playerId];
          r[t] += credits;
          if (t === "group") r.netGroup += credits;
          else if (t === "semi_private") r.netSemiPrivate += credits;
          else r.netPrivate += credits;
        }
        for (const playerId of playerIds) {
          const r = result[playerId];
          const groupDeficit = Math.max(0, -r.netGroup);
          const semiDeficit = Math.max(0, -r.netSemiPrivate);
          const privDeficit = Math.max(0, -r.netPrivate);
          r.groupDebt = groupDeficit;
          r.semiPrivateDebt = semiDeficit;
          r.privateDebt = privDeficit;
          r.totalDebt = groupDeficit + semiDeficit + privDeficit;
          r.hasDebt = r.totalDebt > 0;
        }
        return result;
      },
