      // REPAIR JOB: Fix credit data for a player
      // This repairs:
      // 1. packages.remainingCredits based on actual debit transactions
      // 2. Marks debts with packageId as settled via metadata (but keeps packageId for legacy)
      // 3. Fixes session_players.creditDeductedAt where transactions exist
      async repairPlayerCredits(playerId) {
        const details = [];
        let packagesRepaired = 0;
        let debtsMarkedSettled = 0;
        let sessionPlayersFixed = 0;
        try {
          const playerPackages = await db.select().from(packages).where(eq7(packages.playerId, playerId));
          for (const pkg2 of playerPackages) {
            const debits = await db.select({
              amount: creditTransactions.amount,
              reason: creditTransactions.reason,
              metadata: creditTransactions.metadata
            }).from(creditTransactions).where(and6(
              eq7(creditTransactions.packageId, pkg2.id),
              eq7(creditTransactions.playerId, playerId)
            ));
            let totalDebited = 0;
            for (const d of debits) {
              const meta = d.metadata;
              if (meta?.cancelled === true || meta?.expired === true) continue;
              if (Number(d.amount) < 0) {
                totalDebited += Math.abs(Number(d.amount));
              }
            }
            const correctRemaining = Number(pkg2.totalCredits) - totalDebited;
            if (correctRemaining < Number(pkg2.remainingCredits)) {
              details.push(`Package ${pkg2.id}: ${pkg2.remainingCredits} -> ${correctRemaining} (debited ${totalDebited} of ${pkg2.totalCredits})`);
              await db.update(packages).set({
                remainingCredits: String(correctRemaining),
                status: correctRemaining <= 0 ? "depleted" : "active"
              }).where(eq7(packages.id, pkg2.id));
              packagesRepaired++;
            }
          }
          const debtsWithPackageId = await db.select().from(creditTransactions).where(and6(
            eq7(creditTransactions.playerId, playerId),
            or(
              eq7(creditTransactions.reason, "session_join_debt"),
              eq7(creditTransactions.reason, "session_debt")
            ),
            isNotNull(creditTransactions.packageId)
          ));
          for (const debt of debtsWithPackageId) {
            const meta = debt.metadata || {};
            if (!meta.settled) {
              await db.update(creditTransactions).set({
                packageId: null,
                // Clear packageId - debts should never have it
                metadata: {
                  ...meta,
                  settled: true,
                  settledAt: (/* @__PURE__ */ new Date()).toISOString(),
                  legacyRepair: true,
                  originalPackageId: debt.packageId
                }
              }).where(eq7(creditTransactions.id, debt.id));
              debtsMarkedSettled++;
              details.push(`Debt ${debt.id}: marked as settled, cleared packageId`);
            }
          }
          const sessionsWithDebits = await db.select({
            sessionId: creditTransactions.sessionId,
            transactionId: creditTransactions.id
          }).from(creditTransactions).where(and6(
            eq7(creditTransactions.playerId, playerId),
            eq7(creditTransactions.type, "debit"),
            isNotNull(creditTransactions.sessionId),
            inArray3(creditTransactions.reason, ["session_join", "retrospective_settlement"])
          ));
          for (const item of sessionsWithDebits) {
            if (!item.sessionId) continue;
            const sp = await db.select().from(sessionPlayers).where(and6(
              eq7(sessionPlayers.sessionId, item.sessionId),
              eq7(sessionPlayers.playerId, playerId),
              isNull2(sessionPlayers.creditDeductedAt)
            ));
            if (sp.length > 0) {
              await db.update(sessionPlayers).set({
                creditDeductedAt: /* @__PURE__ */ new Date(),
                creditTransactionId: item.transactionId
              }).where(eq7(sessionPlayers.id, sp[0].id));
              sessionPlayersFixed++;
              details.push(`SessionPlayer ${sp[0].id}: set creditDeductedAt`);
            }
          }
          const balanceByType = await storage.getPlayerCreditBalanceByType(playerId);
          const updatedPackages = await db.select().from(packages).where(eq7(packages.playerId, playerId));
          const remainingByType = { group: 0, semi_private: 0, private: 0 };
          for (const pkg2 of updatedPackages) {
            const ct = pkg2.creditType || "group";
            remainingByType[ct] = (remainingByType[ct] || 0) + Number(pkg2.remainingCredits);
          }
          for (const creditType of ["group", "semi_private", "private"]) {
            const txBalance = Math.max(0, balanceByType[creditType]);
            const pkgRemaining = remainingByType[creditType] || 0;
            if (pkgRemaining > txBalance) {
              const excess = pkgRemaining - txBalance;
              const activeOfType = updatedPackages.filter((p) => (p.creditType || "group") === creditType && Number(p.remainingCredits) > 0).sort((a, b) => Number(a.remainingCredits) - Number(b.remainingCredits));
              let toReduce = excess;
              for (const pkg2 of activeOfType) {
                if (toReduce <= 0) break;
                const currentRemaining = Number(pkg2.remainingCredits);
                const reduction = Math.min(toReduce, currentRemaining);
                const newRemaining = currentRemaining - reduction;
                await db.update(packages).set({
                  remainingCredits: String(newRemaining),
                  status: newRemaining <= 0 ? "depleted" : "active"
                }).where(eq7(packages.id, pkg2.id));
                details.push(`Package ${pkg2.id} (${creditType}): reconciled ${currentRemaining} -> ${newRemaining} (unlinked debts: ${reduction})`);
                packagesRepaired++;
                toReduce -= reduction;
              }
            }
          }
          const nonActivePlayerPackages = await db.select({ id: packages.id, creditType: packages.creditType }).from(packages).where(and6(
            eq7(packages.playerId, playerId),
            ne2(packages.status, "active")
          ));
          for (const pkg2 of nonActivePlayerPackages) {
            try {
              const { converted } = await storage.convertPackageConsumptionToDebt(pkg2.id, playerId);
              if (converted > 0) {
                details.push(`Package ${pkg2.id} (${pkg2.creditType}): backfilled ${converted} depleted session(s) as debt`);
              }
            } catch (err) {
              details.push(`Package ${pkg2.id}: backfill failed \u2014 ${err}`);
            }
          }
          console.log(`[RepairCredits] Player ${playerId}: ${packagesRepaired} packages, ${debtsMarkedSettled} debts, ${sessionPlayersFixed} session_players`);
          return {
            success: true,
            packagesRepaired,
            debtsMarkedSettled,
            sessionPlayersFixed,
            details
          };
        } catch (error) {
          console.error(`[RepairCredits] Error repairing player ${playerId}:`, error);
          return {
            success: false,
            packagesRepaired,
            debtsMarkedSettled,
            sessionPlayersFixed,
            details: [...details, `Error: ${error}`]
          };
        }
      }
