async function awardReferralCard(attendingPlayerId) {
  try {
    const { outsideInvites: outsideInvites2, sessionPlayers: sessionPlayers4 } = await Promise.resolve().then(() => (init_schema(), schema_exports));
    const attendanceCount = await db.select({ id: sessionPlayers4.id }).from(sessionPlayers4).where(
      and11(
        eq13(sessionPlayers4.playerId, attendingPlayerId),
        or4(
          eq13(sessionPlayers4.attendanceStatus, "present"),
          eq13(sessionPlayers4.attendanceStatus, "late")
        )
      )
    ).limit(2);
    if (attendanceCount.length !== 1) return;
    const [invite] = await db.select({ inviterPlayerId: outsideInvites2.inviterPlayerId }).from(outsideInvites2).where(
      and11(
        eq13(outsideInvites2.claimedByPlayerId, attendingPlayerId)
      )
    ).limit(1);
    if (!invite?.inviterPlayerId) return;
    const [card] = await db.select({ id: arenaPlayerCards.id }).from(arenaPlayerCards).where(eq13(arenaPlayerCards.playerId, attendingPlayerId)).limit(1);
    if (!card?.id) return;
    await awardSpecificCard(invite.inviterPlayerId, card.id, "player");
    console.log(
      `[ArenaCardService] awardReferralCard: inviter ${invite.inviterPlayerId} earned card for referred player ${attendingPlayerId}`
    );
  } catch (err) {
    console.error("[ArenaCardService] awardReferralCard failed:", err);
  }
}
