router6.get("/api/glow/players/:playerId/pillars", authMiddlewareWithFreshData, requireAcademy, async (req, res) => {
  try {
    const { playerId } = req.params;
    const academyId = req.user.academyId;
    if (!await validatePlayerAccess(playerId, academyId)) {
      return res.status(404).json({ error: "Player not found" });
    }
    const progress = await db.select().from(playerPillarProgress).where(eq20(playerPillarProgress.playerId, playerId));
    const curriculumPillarMap = /* @__PURE__ */ new Map();
    try {
      const [playerLevel] = await db.select({ levelId: playerBallLevels.levelId }).from(playerBallLevels).where(and18(
        eq20(playerBallLevels.playerId, playerId),
        sql18`${playerBallLevels.status} IN ('active', 'trial')`
      )).limit(1);
      if (playerLevel) {
        const levelSkillsData = await db.select({
          skillId: levelSkills.skillId,
          targetScore: levelSkills.targetScore,
          pillar: glowSkills.pillar
        }).from(levelSkills).innerJoin(glowSkills, eq20(levelSkills.skillId, glowSkills.id)).where(eq20(levelSkills.levelId, playerLevel.levelId));
        const skillIds = levelSkillsData.map((s) => s.skillId);
        const latestScores = /* @__PURE__ */ new Map();
        if (skillIds.length > 0) {
          const scoreRows = await db.select({ skillId: playerSkillScores.skillId, movingAverage: playerSkillScores.movingAverage, score: playerSkillScores.score }).from(playerSkillScores).where(and18(eq20(playerSkillScores.playerId, playerId), inArray9(playerSkillScores.skillId, skillIds))).orderBy(desc11(playerSkillScores.createdAt));
          for (const row of scoreRows) {
            if (!latestScores.has(row.skillId)) {
              latestScores.set(row.skillId, Number(row.movingAverage ?? row.score ?? 0));
            }
          }
        }
        for (const ls of levelSkillsData) {
          const entry = curriculumPillarMap.get(ls.pillar) ?? { achievedCount: 0, skillCount: 0 };
          entry.skillCount += 1;
          const movingAvg = latestScores.get(ls.skillId) ?? 0;
          if (movingAvg >= (ls.targetScore ?? 2)) {
            entry.achievedCount += 1;
          }
          curriculumPillarMap.set(ls.pillar, entry);
        }
      }
    } catch (masteryErr) {
      console.error("[PillarProgress] Curriculum mastery computation failed (non-critical):", masteryErr);
    }
    const PILLAR_NAMES = ["TECHNIQUE", "TACTICAL", "PHYSICAL", "MENTAL", "SOCIAL", "MATCH"];
    const pillarMap = {};
    for (const pillar of PILLAR_NAMES) {
      const existing = progress.find((p) => p.pillar === pillar);
      const curriculum = curriculumPillarMap.get(pillar);
      const skillsTotal = curriculum?.skillCount ?? 0;
      const skillsMastered = curriculum?.achievedCount ?? 0;
      const masteryPct = skillsTotal > 0 ? Math.round(skillsMastered / skillsTotal * 100) : 0;
      pillarMap[pillar] = {
        ...existing || {
          pillar,
          currentScore: 0,
          trend: "stable",
          lastSessionDelta: null
        },
        skillsTotal,
        skillsMastered,
        masteryPct
      };
    }
    res.json({ playerId, pillars: pillarMap });
  } catch (error) {
    console.error("Error fetching pillar progress:", error);
    res.status(500).json({ error: "Failed to fetch pillar progress" });
  }
});
