    const setCount = Math.min(playerScore.length, opponentScore.length);
    const aceEvent = (m.aces ?? 0) > 0 ? 1 : 0;
    const winnerEvent = (m.winners ?? 0) > 0 ? 1 : 0;
    const scoreEvents = setCount + aceEvent + winnerEvent;
