router12.get("/anomalies", authMiddlewareWithFreshData, requireRole("coach", "academy_owner", "platform_owner"), async (req, res) => {
  try {
    const coachId = req.user?.coachId;
    if (!coachId) {
      return res.status(400).json({ error: "Coach ID required" });
    }
    const lookbackDate = /* @__PURE__ */ new Date();
    lookbackDate.setDate(lookbackDate.getDate() - 30);
    const recentScores = await db.select({
      id: playerSkillScores.id,
      playerId: playerSkillScores.playerId,
      skillId: playerSkillScores.skillId,
      score: playerSkillScores.score,
      // Schema column is `created_at` (no separate `scored_at` — when the
      // score row is inserted IS when it was scored). Alias preserves the
      // existing `scoredAt` field on the response payload.
      scoredAt: playerSkillScores.createdAt
    }).from(playerSkillScores).where(and26(
      eq29(playerSkillScores.coachId, coachId),
      gte14(playerSkillScores.createdAt, lookbackDate)
    )).orderBy(desc15(playerSkillScores.createdAt)).limit(50);
    const anomalies = [];
    for (const score of recentScores) {
      const peerScores = await db.select({ avgScore: sql22`AVG(${playerSkillScores.score})` }).from(playerSkillScores).where(and26(
        eq29(playerSkillScores.skillId, score.skillId),
        sql22`${playerSkillScores.coachId} != ${coachId}`
      ));
      const peerAvg = peerScores[0]?.avgScore || 1;
      const deviation = Math.abs(score.score - peerAvg);
      if (deviation > 0.8) {
        const [player] = await db.select({ name: players.name }).from(players).where(eq29(players.id, score.playerId));
        const playerName = player?.name || "Unknown Player";
        anomalies.push({
          id: score.id,
          type: score.score > peerAvg ? "scoring_bias" : "pattern_deviation",
          severity: deviation > 1.5 ? "high" : deviation > 1 ? "medium" : "low",
          playerName,
          description: score.score > peerAvg ? `Score significantly higher than peer average (${score.score} vs ${peerAvg.toFixed(1)})` : `Score pattern deviates from typical progression`,
          detectedAt: score.scoredAt?.toISOString() || (/* @__PURE__ */ new Date()).toISOString(),
          resolved: false
        });
      }
    }
    return res.json(anomalies.slice(0, 10));
  } catch (error) {
    console.error("Error fetching anomalies:", error);
    return res.status(500).json({ error: "Failed to fetch anomalies" });
  }
});
