// server/lib/family-groups.ts
init_db();
init_schema();
init_storage();
import { eq as eq30, sql as sql23 } from "drizzle-orm";
async function resolveOrCreateFamilyForCaller(playerId) {
  const [existing] = await db.select({ familyGroupId: familyMembers.familyGroupId }).from(familyMembers).where(eq30(familyMembers.playerId, playerId)).limit(1);
  if (existing?.familyGroupId) return existing.familyGroupId;
  const [player] = await db.select().from(players).where(eq30(players.id, playerId));
  if (!player) {
    throw new Error(`resolveOrCreateFamilyForCaller: player ${playerId} not found`);
  }
  if (player.parentEmail) {
    const parentEmail = player.parentEmail.trim().toLowerCase();
    if (parentEmail) {
      const parentRows = await db.select().from(players).where(sql23`LOWER(TRIM(${players.email})) = ${parentEmail}`).limit(1);
      const parentPlayer = parentRows[0];
      if (parentPlayer) {
        const parentGroupId = await ensureGroupForCreator(parentPlayer.id);
        await addPlayerToFamily(parentGroupId, player.id, {
          addedByPlayerId: parentPlayer.id,
          addedWithPin: false
        });
        return parentGroupId;
      }
    }
  }
  return ensureGroupForCreator(playerId);
}
async function ensureGroupForCreator(playerId) {
  const [existingMembership] = await db.select({ familyGroupId: familyMembers.familyGroupId }).from(familyMembers).where(eq30(familyMembers.playerId, playerId)).limit(1);
  if (existingMembership?.familyGroupId) return existingMembership.familyGroupId;
  const [group] = await db.insert(familyGroups).values({ createdByPlayerId: playerId }).returning({ id: familyGroups.id });
  await db.insert(familyMembers).values({
    familyGroupId: group.id,
    playerId,
    roleLabel: "creator",
    addedByPlayerId: playerId,
    addedWithPin: false
  });
  await syncFamilyChatGroup(group.id);
  return group.id;
}
async function addPlayerToFamily(groupId, playerId, opts = {
  addedByPlayerId: null
}) {
  const existing = await db.select({
    id: familyMembers.id,
    familyGroupId: familyMembers.familyGroupId
  }).from(familyMembers).where(eq30(familyMembers.playerId, playerId));
  for (const row of existing) {
    if (row.familyGroupId === groupId) return;
  }
  if (existing.length > 0) {
    throw new Error(
      `addPlayerToFamily: player ${playerId} already belongs to family ${existing[0].familyGroupId}`
    );
  }
  await db.insert(familyMembers).values({
    familyGroupId: groupId,
    playerId,
    roleLabel: opts.roleLabel ?? "member",
    addedByPlayerId: opts.addedByPlayerId,
    addedWithPin: opts.addedWithPin ?? false
  });
  await syncFamilyChatGroup(groupId);
}
async function getFamilyMemberIds(callerPlayerId) {
  const groupId = await resolveOrCreateFamilyForCaller(callerPlayerId);
  const rows = await db.select({ playerId: familyMembers.playerId }).from(familyMembers).where(eq30(familyMembers.familyGroupId, groupId));
  return rows.map((r) => r.playerId);
}
async function findFamilyForPlayer(playerId) {
  const [row] = await db.select({ familyGroupId: familyMembers.familyGroupId }).from(familyMembers).where(eq30(familyMembers.playerId, playerId)).limit(1);
  return row?.familyGroupId ?? null;
}

