var router13 = Router12();
function splitName(name) {
  const trimmed = (name || "").trim();
  if (!trimmed) return { firstName: "", lastName: "" };
  const parts = trimmed.split(/\s+/);
  if (parts.length === 1) return { firstName: parts[0], lastName: "" };
  return { firstName: parts[0], lastName: parts.slice(1).join(" ") };
}
async function getCallerChildPlayerIds(userId) {
  const freshUser = await storage.getUserById(userId);
  if (!freshUser || !freshUser.playerId) return [];
  const memberIds = await getFamilyMemberIds(freshUser.playerId).catch(() => []);
  const others = memberIds.filter((id) => id !== freshUser.playerId);
  if (others.length > 0) return others;
  const callerPlayer = await storage.getPlayer(freshUser.playerId);
  const callerEmail = (callerPlayer?.email || freshUser.email || "").trim().toLowerCase();
  if (!callerEmail) return [];
  const linkedRows = await db.select({ id: players.id }).from(players).where(
    or9(
      sql24`LOWER(TRIM(${players.parentEmail})) = ${callerEmail}`,
      and27(sql24`LOWER(TRIM(${players.email})) = ${callerEmail}`, sql24`${players.id} <> ${freshUser.playerId}`)
    )
  );
  return linkedRows.map((r) => r.id);
}
async function isCallerChildOf(userId, playerId) {
  const ids = await getCallerChildPlayerIds(userId);
  return ids.includes(playerId);
}
