async function resolveTargetPostId(idOrFeedItemId) {
  const [direct] = await db.select({ id: posts.id }).from(posts).where(eq43(posts.id, idOrFeedItemId)).limit(1);
  if (direct) return direct.id;
  const [feedItem] = await db.select().from(feedItems).where(eq43(feedItems.id, idOrFeedItemId)).limit(1);
  if (!feedItem) return null;
  if (feedItem.postId) return feedItem.postId;
  if (!feedItem.authorUserId) return null;
  let academyId = feedItem.academyId;
  if (!academyId) {
    const [u] = await db.select({ academyId: users.academyId }).from(users).where(eq43(users.id, feedItem.authorUserId)).limit(1);
    academyId = u?.academyId || null;
  }
  const captionFromPayload = typeof feedItem.payload?.summary === "string" ? feedItem.payload.summary : typeof feedItem.payload?.title === "string" ? feedItem.payload.title : null;
  const scope = feedItem.scope || "academy";
  let visibility = "public";
  if (scope === "academy") visibility = "academy";
  else if (scope === "friends") visibility = "friends";
  else if (scope === "squad") visibility = "group";
  let createdPostId = null;
  await db.transaction(async (tx) => {
    const [recheck] = await tx.select({ postId: feedItems.postId }).from(feedItems).where(eq43(feedItems.id, feedItem.id)).limit(1);
    if (recheck?.postId) {
      createdPostId = recheck.postId;
      return;
    }
    const [inserted] = await tx.insert(posts).values({
      authorId: feedItem.authorUserId,
      academyId,
      feedItemId: feedItem.id,
      contextType: feedItem.sourceType,
      contextId: feedItem.sourceId || null,
      caption: captionFromPayload,
      mediaUrls: [],
      mediaTypes: [],
      visibility,
      groupId: feedItem.groupId || null,
      taggedUserIds: [],
      cheerCount: 0,
      commentCount: 0
    }).returning({ id: posts.id });
    createdPostId = inserted.id;
    await tx.update(feedItems).set({ postId: inserted.id }).where(eq43(feedItems.id, feedItem.id));
  });
  return createdPostId;
}
