router23.post("/api/social/posts/upload-images", authMiddlewareWithFreshData, requireFeatureUnlock("community_feed"), socialPostUploadHandler, async (req, res) => {
  const files = req.files || [];
  const fileSummary = files.map((f) => ({
    originalname: f.originalname,
    mimetype: f.mimetype,
    bytes: f.size
  }));
  try {
    if (files.length === 0) {
      return res.status(400).json({ error: "No files uploaded", code: "NO_FILES" });
    }
    const uploadResults = await Promise.all(
      files.map(async (file) => {
        const publicUrl = await uploadToSupabase(
          file.buffer,
          file.originalname,
          file.mimetype
        );
        return publicUrl;
      })
    );
    res.json({
      success: true,
      images: uploadResults,
      count: uploadResults.length
    });
  } catch (error) {
    if (error instanceof SupabaseStorageError) {
      console.error("[Social] Supabase storage error during upload", {
        code: error.code,
        statusCode: error.statusCode,
        details: error.details,
        fileCount: files.length,
        files: fileSummary
      });
      return res.status(502).json({
        error: "Couldn't reach storage. Please try again.",
        code: "STORAGE_UNAVAILABLE"
      });
    }
    console.error("[Social] Unexpected error uploading to Supabase Storage", {
      error: error instanceof Error ? { message: error.message, name: error.name } : error,
      fileCount: files.length,
      files: fileSummary
    });
    res.status(500).json({ error: "Upload failed", code: "UPLOAD_FAILED" });
  }
});
