async function enrollPlayerInGroupSession(sessionId, playerId, onEnrolled) {
  try {
    return await db.transaction(async (tx) => {
      const [session] = await tx.select().from(sessions).where(eq47(sessions.id, sessionId)).limit(1);
      if (!session) {
        return { ok: false, reason: "session_gone" };
      }
      if (session.status === "cancelled") {
        return { ok: false, reason: "session_cancelled" };
      }
      const enrolledRows = await tx.select({ playerId: sessionPlayers.playerId }).from(sessionPlayers).where(eq47(sessionPlayers.sessionId, sessionId));
      const alreadyIn = enrolledRows.some((r) => r.playerId === playerId);
      if (alreadyIn) {
        return { ok: true, alreadyIn: true };
      }
      const offeredRows = await tx.select({ id: sessionWaitlist.id }).from(sessionWaitlist).where(
        and40(
          eq47(sessionWaitlist.sessionId, sessionId),
          eq47(sessionWaitlist.status, "offered")
        )
      );
      const maxPlayers = session.maxPlayers ?? 6;
      if (enrolledRows.length + offeredRows.length >= maxPlayers) {
        return { ok: false, reason: "full" };
      }
      await tx.insert(sessionPlayers).values({
        sessionId,
        playerId
      });
      if (onEnrolled) {
        await onEnrolled(tx);
      }
      return { ok: true, alreadyIn: false };
    });
  } catch (err) {
    console.error(
      `[SessionEnrolment] enrollPlayerInGroupSession(session=${sessionId}, player=${playerId}) failed:`,
      err
    );
    return { ok: false, reason: "session_gone" };
  }
}

