router31.post("/api/quests/claim-chain-bonus", authMiddlewareWithFreshData, async (req, res) => {
  try {
    const playerId = req.user.playerId;
    const questType = req.body?.type;
    if (!playerId) {
      return res.status(400).json({ error: "Player context required" });
    }
    if (!questType || !["daily", "weekly", "monthly"].includes(questType)) {
      return res.status(400).json({ error: "Invalid quest type \u2014 must be daily, weekly, or monthly" });
    }
    const CHAIN_BONUS_XP = 50;
    const periodKey = getChainBonusPeriodKey(questType);
    const [existingClaim] = await db.select().from(questChainBonusClaims).where(and47(
      eq54(questChainBonusClaims.playerId, playerId),
      eq54(questChainBonusClaims.questType, questType),
      eq54(questChainBonusClaims.periodKey, periodKey)
    ));
    if (existingClaim) {
      return res.status(400).json({ error: `${questType} chain bonus already claimed for this period` });
    }
    if (questType === "daily") {
      const today = periodKey;
      const [slot] = await db.select().from(dailyQuestSlots).where(and47(
        eq54(dailyQuestSlots.playerId, playerId),
        eq54(dailyQuestSlots.slotDate, today)
      ));
      if (!slot) {
        return res.status(404).json({ error: "No daily quest slot found for today" });
      }
      if (!slot.bonusUnlocked) {
        return res.status(400).json({ error: "Complete all daily quests first to unlock the chain bonus" });
      }
      await db.update(dailyQuestSlots).set({ bonusClaimed: true }).where(eq54(dailyQuestSlots.id, slot.id));
    } else {
      const now = /* @__PURE__ */ new Date();
      const activeQuests = await db.select({ quest: playerQuests }).from(playerQuests).innerJoin(questTemplates, eq54(playerQuests.questTemplateId, questTemplates.id)).where(and47(
        eq54(playerQuests.playerId, playerId),
        eq54(questTemplates.questType, questType),
        gte24(playerQuests.expiresAt, now)
      ));
      if (activeQuests.length === 0) {
        return res.status(404).json({ error: `No active ${questType} quests found` });
      }
      if (!activeQuests.every((q) => q.quest.status === "claimed")) {
        return res.status(400).json({ error: `Claim all ${questType} quest rewards first to unlock the chain bonus` });
      }
    }
    await db.insert(questChainBonusClaims).values({
      playerId,
      questType,
      periodKey,
      xpAwarded: CHAIN_BONUS_XP
    });
    await db.update(players).set({ totalXp: sql33`COALESCE(total_xp, 0) + ${CHAIN_BONUS_XP}` }).where(eq54(players.id, playerId));
    const [updatedPlayer] = await db.select({ totalXp: players.totalXp, glowCoins: players.glowCoins }).from(players).where(eq54(players.id, playerId));
    res.json({
      success: true,
      bonusXpAwarded: CHAIN_BONUS_XP,
      newTotalXp: updatedPlayer?.totalXp || 0,
      newGlowCoins: updatedPlayer?.glowCoins || 0
    });
  } catch (error) {
    if (error?.code === "23505") {
      return res.status(400).json({ error: "Chain bonus already claimed for this period" });
    }
    console.error("Error claiming chain bonus:", error);
    res.status(500).json({ error: "Failed to claim chain bonus" });
  }
});
