router31.post("/api/player/connections/:connectionId/respond", authMiddlewareWithFreshData, async (req, res) => {
  const { connectionId } = req.params;
  const action = req.body?.action;
  const playerId = req.user.playerId;
  const userId = req.user.userId;
  try {
    if (!playerId) {
      console.warn("[FriendRespond] missing playerId", { userId, connectionId, action });
      return res.status(403).json({ error: "Switch to a player profile to respond to friend requests." });
    }
    if (!["accept", "decline"].includes(action)) {
      return res.status(400).json({ error: "Invalid action" });
    }
    let [connection] = await db.select().from(playerConnections).where(eq54(playerConnections.id, connectionId));
    let resolvedConnectionId = connectionId;
    if (!connection) {
      try {
        const fallbackRows = await db.select().from(playerConnections).where(
          and47(
            eq54(playerConnections.player2Id, playerId),
            eq54(playerConnections.player1Id, connectionId),
            eq54(playerConnections.status, "pending")
          )
        );
        if (fallbackRows.length === 1) {
          connection = fallbackRows[0];
          resolvedConnectionId = connection.id;
          console.log("[FriendRespond] resolved via player-id fallback", {
            playerId,
            paramConnectionId: connectionId,
            resolvedConnectionId,
            action
          });
        } else if (fallbackRows.length > 1) {
          console.warn("[FriendRespond] player-id fallback ambiguous", {
            playerId,
            paramConnectionId: connectionId,
            matches: fallbackRows.length
          });
        }
      } catch (fallbackErr) {
        console.error("[FriendRespond] player-id fallback lookup failed", fallbackErr);
      }
    }
    if (!connection) {
      if (action === "decline") {
        console.log("[FriendRespond] decline on missing connection \u2014 treating as success", { playerId, connectionId });
        return res.json({ success: true, action, alreadyHandled: true });
      }
      console.warn("[FriendRespond] connection not found", { playerId, connectionId, action });
      return res.status(404).json({ error: "Friend request not found. It may have been cancelled." });
    }
    const isReceiver = connection.player2Id === playerId;
    const isRequester = connection.player1Id === playerId;
    console.log("[FriendRespond] entry", {
      playerId,
      connectionId,
      action,
      connectionStatus: connection.status,
      player1Id: connection.player1Id,
      player2Id: connection.player2Id,
      isReceiver,
      isRequester
    });
    if (!isReceiver && !isRequester) {
      return res.status(403).json({ error: "You can't respond to this friend request from this account." });
    }
    if (connection.status === "accepted") {
      console.log("[FriendRespond] connection already accepted \u2014 idempotent success", { playerId, connectionId, action });
      return res.json({ success: true, action, alreadyHandled: true });
    }
    if (!isReceiver) {
      return res.status(403).json({ error: "Only the recipient can respond to this friend request." });
    }
    if (connection.status !== "pending") {
      console.warn("[FriendRespond] unexpected status", { playerId, connectionId, status: connection.status });
      return res.status(400).json({ error: `Friend request is no longer actionable (status: ${connection.status}).` });
    }
    if (action === "accept") {
      await db.update(playerConnections).set({ status: "accepted", acceptedAt: /* @__PURE__ */ new Date() }).where(eq54(playerConnections.id, resolvedConnectionId));
      try {
        const [accepter] = await db.select({ name: players.name }).from(players).where(eq54(players.id, playerId)).limit(1);
        const requesterTokens = await getPlayerPushTokens(connection.player1Id);
        if (requesterTokens.length > 0) {
          await sendPushNotification(
            requesterTokens,
            "Friend Request Accepted",
            `${accepter?.name || "A player"} accepted your friend request`,
            { type: "friend_request_accepted", playerId: connection.player1Id, screen: "FriendsList" }
          );
        } else {
          await db.insert(playerNotifications).values({
            playerId: connection.player1Id,
            title: "Friend Request Accepted",
            body: `${accepter?.name || "A player"} accepted your friend request`,
            type: "friend_request_accepted",
            data: { connectionId: resolvedConnectionId, otherPlayerId: playerId }
          });
        }
      } catch (notifyErr) {
        console.error("[FriendRequest] Failed to send accept notification:", notifyErr);
      }
    } else {
      await db.delete(playerConnections).where(eq54(playerConnections.id, resolvedConnectionId));
    }
    res.json({ success: true, action });
  } catch (error) {
    console.error("[FriendRespond] unhandled error", { playerId, connectionId, action, error });
    res.status(500).json({ error: "Something went wrong while updating the friend request. Please try again." });
  }
});
