    const { email, name, reason, comments } = req.body;
    if (!email || !name) {
      return res.status(400).json({ error: "Email and name are required" });
    }
    const { sendDeleteAccountRequestEmail: sendDeleteAccountRequestEmail2 } = await Promise.resolve().then(() => (init_emailService(), emailService_exports));
    const result = await sendDeleteAccountRequestEmail2({
      userEmail: email,
      userName: name,
      reason,
      comments
    });
    if (result.success) {
      res.json({ success: true, message: "Deletion request submitted successfully" });
    } else {
      console.error("Failed to send delete account email:", result.error);
      res.json({ success: true, message: "Deletion request submitted" });
    }
