router37.post(
  "/api/platform/academies/:id/members",
  authMiddlewareWithFreshData,
  requireRole("platform_owner"),
  async (req, res) => {
    try {
      const academyId = req.params.id;
      const { userId, role } = req.body;
      if (!userId) {
        return res.status(400).json({ error: "User ID is required" });
      }
      if (!role || !["academy_owner", "coach", "assistant"].includes(role)) {
        return res.status(400).json({
          error: "Valid role (academy_owner, coach, assistant) is required"
        });
      }
      const academy = await storage.getAcademy(academyId);
      if (!academy) {
        return res.status(404).json({ error: "Academy not found" });
      }
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }
      let coachId = user.coachId;
      if (!coachId) {
        const newCoach = await storage.createCoach({
          name: user.username,
          email: user.email,
          academyId
        });
        coachId = newCoach.id;
        await storage.updateUser(userId, {
          coachId,
          role,
          academyId
        });
      }
      const existingMembership = await storage.getCoachAcademyMembership(
        coachId,
        academyId
      );
      if (existingMembership) {
        await storage.updateCoachAcademyMembership(existingMembership.id, {
          role,
          isActive: true
        });
      } else {
        await storage.createCoachAcademyMembership({
          coachId,
          academyId,
          role,
          isActive: true,
          isPrimary: !user.academyId
          // Make primary if user has no academy
        });
      }
      if (!user.academyId) {
        await storage.updateUser(userId, { academyId });
      }
      res.status(201).json({
        success: true,
        message: `User added to academy as ${role}`,
        membership: { userId, coachId, academyId, role }
      });
    } catch (error) {
      console.error("Add member to academy error:", error);
      res.status(500).json({ error: "Failed to add member to academy" });
    }
  }
);
router37.post(
  "/api/platform/academies/:id/users",
  authMiddlewareWithFreshData,
  requireRole("platform_owner"),
  async (req, res) => {
    try {
      const academyId = req.params.id;
      const { username, email, password, role, name, ballLevel } = req.body;
      if (!username || !password) {
        return res.status(400).json({ error: "Username and password are required" });
      }
      if (!role || !["academy_owner", "coach", "assistant", "player"].includes(role)) {
        return res.status(400).json({ error: "Valid role is required" });
      }
      const academy = await storage.getAcademy(academyId);
      if (!academy) {
        return res.status(404).json({ error: "Academy not found" });
      }
      const existingUser = await storage.getUserByUsername(
        username.toLowerCase()
      );
      if (existingUser) {
        return res.status(400).json({ error: "Username already exists" });
      }
      const bcrypt4 = await import("bcrypt");
      const hashedPassword = await bcrypt4.hash(password, 10);
      const newUserData = { username: username.toLowerCase(), email: email || `${username.toLowerCase()}@glow.local`, password: hashedPassword, role, status: "active", academyId };
      const newUser = await storage.createUser(newUserData);
      if (["academy_owner", "coach", "assistant"].includes(role)) {
        const newCoach = await storage.createCoach({
          name: name || username,
          email: newUser.email,
          academyId
        });
        await storage.updateUser(newUser.id, { coachId: newCoach.id });
        await storage.createCoachAcademyMembership({
          coachId: newCoach.id,
          academyId,
          role,
          isActive: true,
          isPrimary: true
        });
      }
      if (role === "player") {
        const newPlayer = await storage.createPlayer({
          name: name || username,
          academyId,
          status: "active",
          ballLevel: ballLevel || "green"
        });
        await storage.updateUser(newUser.id, { playerId: newPlayer.id });
      }
      res.status(201).json({
        success: true,
        message: `New ${role} account created`,
        user: {
          id: newUser.id,
          username: newUser.username,
          email: newUser.email,
          role: newUser.role
        }
      });
    } catch (error) {
      console.error("Create user for academy error:", error);
      res.status(500).json({ error: "Failed to create user" });
    }
  }
);
