router62.get(
  "/api/admin/players/:id/credit-audit",
  authMiddlewareWithFreshData,
  requireRole("admin", "academy_owner", "platform_owner"),
  async (req, res) => {
    try {
      const playerId = req.params.id;
      const academyId = req.user?.academyId;
      const player = await storage.getPlayer(playerId, academyId ?? void 0);
      if (!player) {
        return res.status(404).json({ error: "Player not found" });
      }
      const ledgerRows = await db.select().from(creditLedgerV2).where(eq87(creditLedgerV2.playerId, playerId)).orderBy(creditLedgerV2.occurredAt);
      const lotRows = await db.select().from(creditLots).where(eq87(creditLots.playerId, playerId));
      const allSessionPlayers = await db.select({
        id: sessionPlayers.id,
        sessionId: sessionPlayers.sessionId,
        attendanceStatus: sessionPlayers.attendanceStatus
      }).from(sessionPlayers).where(eq87(sessionPlayers.playerId, playerId));
      const sessionIds = [...new Set(
        allSessionPlayers.map((sp) => sp.sessionId).filter((id) => id !== null)
      )];
      let sessionDetails = {};
      if (sessionIds.length > 0) {
        const sessRows = await db.select({
          id: sessions.id,
          sessionType: sessions.sessionType,
          // sessions has no `date` column; the canonical schedule
          // anchor is `startTime`. Aliased to keep the existing
          // `date` field in the response payload.
          date: sessions.startTime,
          duration: sessions.duration,
          status: sessions.status
        }).from(sessions).where(inArray45(sessions.id, sessionIds.filter((id) => id !== null)));
        for (const s of sessRows) {
          sessionDetails[s.id] = s;
        }
      }
      const balance = await storage.getPlayerCreditBalanceByType(playerId);
      const txSummary = ledgerRows.map((row) => ({
        id: row.id,
        amount: Number(row.delta),
        creditType: row.type,
        reason: row.reason,
        type: row.type,
        packageId: row.lotId,
        sessionId: row.sessionId,
        metadata: row.metadata,
        createdAt: row.occurredAt,
        includedInBalance: Number(row.delta) !== 0,
        isSettledDebt: false
      }));
      const attendedSessions = allSessionPlayers.filter((sp) => sp.attendanceStatus === "present" || sp.attendanceStatus === "late");
      const debitSessionIds = new Set(
        ledgerRows.filter((row) => Number(row.delta) < 0 && row.sessionId && row.reason === "consume").map((row) => row.sessionId)
      );
      const missingSessions = attendedSessions.filter((sp) => !debitSessionIds.has(sp.sessionId)).filter((sp) => sessionDetails[sp.sessionId]?.status !== "cancelled").map((sp) => ({
        sessionId: sp.sessionId,
        sessionDetails: sessionDetails[sp.sessionId] || null
      }));
      res.json({
        player: { id: player.id, name: player.name },
        computedBalance: balance,
        transactions: txSummary,
        packages: lotRows.map((lot) => ({
          id: lot.id,
          creditType: lot.type,
          totalCredits: Number(lot.qtyTotal),
          remainingCredits: Number(lot.qtyRemaining),
          status: lot.status,
          expiryDate: lot.expiresAt,
          createdAt: lot.createdAt
        })),
        sessionPlayers: attendedSessions.map((sp) => ({
          sessionPlayerId: sp.id,
          sessionId: sp.sessionId,
          attendanceStatus: sp.attendanceStatus,
          sessionDetails: sessionDetails[sp.sessionId] || null,
          hasDebitTransaction: debitSessionIds.has(sp.sessionId)
        })),
        missingSessions,
        summary: {
          totalTransactions: ledgerRows.length,
          activeTransactions: txSummary.filter((t) => t.includedInBalance).length,
          settledTransactions: txSummary.filter((t) => t.metadata?.settled === true).length,
          cancelledTransactions: txSummary.filter((t) => t.metadata?.cancelled === true).length,
          totalPackages: lotRows.length,
          totalSessionsAttended: attendedSessions.length,
          sessionsWithoutDebit: missingSessions.length
        }
      });
    } catch (error) {
      console.error("Credit audit error:", error);
      res.status(500).json({ error: "Failed to generate credit audit" });
    }
  }
);
