var RC_API_SECRET2 = process.env.REVENUECAT_API_SECRET;
async function verifyIAPWithRevenueCat(appUserId, productId, transactionId) {
  if (!RC_API_SECRET2) {
    return process.env.NODE_ENV === "development";
  }
  try {
    const res = await fetch(
      `https://api.revenuecat.com/v1/subscribers/${encodeURIComponent(appUserId)}`,
      {
        headers: {
          Authorization: `Bearer ${RC_API_SECRET2}`,
          "Content-Type": "application/json"
        }
      }
    );
    if (!res.ok) return false;
    const body = await res.json();
    const purchases = body.subscriber?.non_subscriptions?.[productId] ?? [];
    if (purchases.length > 0 || transactionId) {
      if (!transactionId) return false;
      return purchases.some((p) => p.id === transactionId);
    }
    const subs = body.subscriber?.subscriptions ?? {};
    if (subs[productId]) {
      const sub = subs[productId];
      return sub.expires_date === null || new Date(sub.expires_date).getTime() > Date.now();
    }
    return false;
  } catch {
    return false;
  }
}
